import { Component, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';
import { DataService } from '../../services/data.service';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-products',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './products.component.html',
  styleUrl: './products.component.css'
})
export class ProductsComponent {
  carrito = signal<Record<number, number>>({});
  comprando = signal(false);

  constructor(public data: DataService, public auth: AuthService, private router: Router) {}

  cantidadEnCarrito(productoId: number): number {
    return this.carrito()[productoId] ?? 0;
  }

  agregar(productoId: number) {
    this.carrito.update(c => ({ ...c, [productoId]: (c[productoId] ?? 0) + 1 }));
  }

  quitar(productoId: number) {
    this.carrito.update(c => {
      const actual = (c[productoId] ?? 0) - 1;
      const copia = { ...c };
      if (actual <= 0) delete copia[productoId]; else copia[productoId] = actual;
      return copia;
    });
  }

  itemsCarrito = computed(() => {
    const carrito = this.carrito();
    return this.data.productos()
      .filter(p => carrito[p.id] > 0)
      .map(p => ({ producto: p, cantidad: carrito[p.id] }));
  });

  totalCarrito = computed(() =>
    this.itemsCarrito().reduce((sum, it) => sum + it.producto.precio * it.cantidad, 0)
  );

  comprar() {
    const usuario = this.auth.usuario();
    const nombreCliente = usuario ? usuario.nombre : 'Cliente';
    const items = this.itemsCarrito().map(it => ({ productoId: it.producto.id, cantidad: it.cantidad }));
    if (items.length === 0) return;

    this.comprando.set(true);
    this.data.comprarProductos(nombreCliente, items, venta => {
      this.comprando.set(false);
      this.router.navigate(['/pagar/venta', venta.id]);
    });
  }

  formatPrecio(valor: number): string {
    return '$' + valor.toLocaleString('es-CO');
  }
}
<div class="booking-shell">
  <header class="booking-top">
    <a routerLink="/" class="booking-brand">
      <span class="booking-mark">K</span> Kutt
    </a>
    <div class="booking-nav">
      <a routerLink="/agendar">Agendar cita</a>
      <a routerLink="/mis-citas">Mis citas</a>
      <a routerLink="/productos" class="active">Productos</a>
      <span class="booking-user" *ngIf="auth.usuario()">{{ auth.usuario()?.nombre }}</span>
      <button class="booking-logout" *ngIf="auth.usuario()" (click)="auth.logout()">Salir</button>
    </div>
  </header>

  <main class="booking-main" style="max-width:900px;">
    <h2 style="font-size:22px; margin-bottom:6px;">Productos</h2>
    <p class="step-sub">Agrega lo que quieras y paga por separado, sin necesidad de una cita.</p>

    <div class="prod-grid">
      <div class="prod-card" *ngFor="let p of data.productos()">
        <div class="prod-icon"></div>
        <p class="prod-name">{{ p.nombre }}</p>
        <p class="prod-price">{{ formatPrecio(p.precio) }}</p>
        <p class="prod-stock" [class.low]="p.existencias <= p.minimo">
          {{ p.existencias > 0 ? p.existencias + ' disponibles' : 'Agotado' }}
        </p>

        <div class="prod-cart-controls" *ngIf="p.existencias > 0">
          <button (click)="quitar(p.id)" [disabled]="cantidadEnCarrito(p.id) === 0">\u2212</button>
          <span>{{ cantidadEnCarrito(p.id) }}</span>
          <button (click)="agregar(p.id)" [disabled]="cantidadEnCarrito(p.id) >= p.existencias">+</button>
        </div>
      </div>
    </div>

    <div class="cart-summary" *ngIf="itemsCarrito().length > 0">
      <div class="cart-head">
        <span>{{ itemsCarrito().length }} producto(s) en el carrito</span>
        <strong>{{ formatPrecio(totalCarrito()) }}</strong>
      </div>
      <button class="btn-gold" [disabled]="comprando()" (click)="comprar()">
        {{ comprando() ? 'Procesando...' : 'Continuar a pagar' }}
      </button>
    </div>
  </main>
</div>
